import numpy as np
from scipy.optimize import least_squares
lam=1.5406
def pv(x,x0,fwhm,eta=0.5):
    s=fwhm/2
    return eta/(1+((x-x0)/s)**2)+(1-eta)*np.exp(-np.log(2)*((x-x0)/s)**2)
def inst(tt,opt):
    t=np.tan(np.radians(tt))
    U,V,W=(0.012,-0.002,0.0085) if opt=='std' else (0.0011,-0.00018,0.00077)
    return np.sqrt(np.maximum(U*t*t+V*t+W,1e-8))
MM={(1,1,0):12,(2,0,0):6,(2,1,1):24,(2,2,0):12,(3,1,0):24,(2,2,2):8,(3,2,1):48,(4,0,0):6,(3,3,0):12,(4,1,1):24,(3,3,2):24,(4,2,0):24}
def peaks_bcc(a,tt,opt,L,mults=1.0):
    y=np.zeros_like(tt)
    for hkl,mm in MM.items():
        h2=sum(i*i for i in hkl)
        s=lam/(2*a/np.sqrt(h2))
        if s>=1: continue
        th2=2*np.degrees(np.arcsin(s)); th=np.radians(th2/2)
        lp=(1+np.cos(2*th)**2)/(np.sin(th)**2*np.cos(th))
        fw=np.sqrt(inst(th2,opt)**2+(0.9*lam/(L*np.cos(th))*180/np.pi)**2)
        y+=mm*lp*pv(tt,th2,fw)
    return y
