def ym_(tt,opt,L,r=0.5):
    return r*peaks_bcc(3.1472,tt,opt,L)+(1-r)*peaks_bcc(3.1652,tt,opt,L)
def dchi(tt,opt,L,k,bg,Lfit_range=0.3,sig=None):
    # truth: alloy with size L, counts = k*ya + bg
    ya=ya_(tt,opt,L)*k+bg
    best=np.inf
    for Lf in np.linspace(L*0.7,L*1.3,13):
        for r in np.linspace(0.2,0.8,13):
            for dz in np.linspace(-0.01,0.01,5):
                mdl=ym_(tt-dz,opt,Lf,r)*k+bg
