                c,*_=np.linalg.lstsq(A*w[:,None],ya*0+ (ya) *w,rcond=None)
                # model counts: use Pearson chi2
                mu=A@c
                mu=np.maximum(mu,1e-6)
                chi=np.sum((ya-mu)**2/mu)
                best=min(best,chi)
    return best
